  yield SAY(H, 'sad', T('Rendors-toi, frangin. Un jour, quelqu’un viendra te voir, toi aussi.', 'Go back to sleep, brother. One day someone will come and see you too.', 'Ξανακοιμήσου, αδερφέ. Μια μέρα θα έρθει κάποιος να δει κι εσένα.'));
  yield SAY(H, 'neutral', T('Bon. Elle ne s’arrêtera pas. Alors tu vas l’arrêter, et je vais t’aider de la seule façon que je connais.', 'Right. She won’t stop. So you’re going to stop her, and I’ll help the only way I know.', 'Λοιπόν. Δεν θα σταματήσει. Οπότε θα τη σταματήσεις εσύ, κι εγώ θα σε βοηθήσω με τον μόνο τρόπο που ξέρω.'));
  yield* walkTo$(H, 250, 50); for (let i = 0; i < 3; i++) { yield* anim$(H, 'club'); Audio.sfx('clang'); for (let j = 0; j < 8; j++) G.parts.push({ x: H.x + 14, y: H.y - 18, vx: (Math.random() - 0.3) * 120, vy: -40 - Math.random() * 60, life: 0.5, max: 0.5, kind: 'ember', g: 200 }); } yield* walkTo$(H, h.x - 40, 40); face(H, h);
  yield SAY(H, 'tender', T('Trois liens. On ne les voit qu’avec les yeux des dieux. J’en ai déjà fait, une fois, pour elle. Elle a boudé trois cents ans.', 'Three bonds. You can only see them with a god’s eyes. I made a set once before, for her. She sulked for three hundred years.', 'Τρεις δεσμοί. Φαίνονται μόνο με τα μάτια των θεών. Είχα φτιάξει μια φορά, γι’ αυτήν. Μούτρωνε τριακόσια χρόνια.'));
  yield SAY(H, 'sad', T('Je ne peux pas monter avec toi. Le serment : un dieu ne peut pas se tenir à côté de son enfant mortel devant les autres. Je ne peux pas dire ce que tu es pour moi. … Je peux te fabriquer quelque chose.', 'I can’t come up with you. The oath: a god can’t stand beside his mortal child in front of the others. I can’t say what you are to me. …I can make you something.', 'Δεν μπορώ να ανέβω μαζί σου. Ο όρκος: ένας θεός δεν μπορεί να σταθεί δίπλα στο θνητό παιδί του μπροστά στους άλλους. Δεν μπορώ να πω τι είσαι για μένα. … Μπορώ να σου φτιάξω κάτι.'));
