function* sceneArgusIn() { const h = G.hero, m = byName('mentor'), A = byName('argus'), c = companion(); G.letterbox = 1; yield* walkTo$(h, ARG_X - 160, 46); face(h, A);
  yield SAY(m, 'think', T('Argos aux cent yeux. Hermès l’a tué il y a longtemps, et Héra a semé ses yeux dans la queue de son paon. C’est lui qui te regardait, tout ce temps. Ses yeux voient les deux mondes : changer de vue ne te cachera pas.', 'Argus the hundred-eyed. Hermes killed him long ago, and Hera set his eyes in her peacock’s tail. That’s who has been watching you all along. His eyes see both worlds: switching views won’t hide you.', 'Ο πανόπτης Άργος. Ο Ερμής τον σκότωσε πριν πολύ καιρό, κι η Ήρα έβαλε τα μάτια του στην ουρά του παγωνιού της. Αυτός σε κοίταζε όλο αυτό τον καιρό. Τα μάτια του βλέπουν και τους δύο κόσμους: η αλλαγή όρασης δεν θα σε κρύψει.'));
  yield SAY(m, 'neutral', T('Quand il fait la roue, des colonnes de lumière vont tomber l’une après l’autre. Reste entre elles. Après, il est ébloui par son propre spectacle.', 'When he fans his tail, columns of light will fall one after another. Stay between them. Afterwards, he’s dazzled by his own show.', 'Όταν ανοίγει την ουρά, στήλες φωτός θα πέφτουν η μία μετά την άλλη. Μείνε ανάμεσά τους. Μετά, θαμπώνεται απ’ το ίδιο του το θέαμα.'));
  if (c && c.id === 'asterion') yield SAY(c, 'happy', T('Cent yeux ! Je vais les compter. … Quatre-vingt-dix-neuf. Il en cligne un.', 'A hundred eyes! I’ll count them. …Ninety-nine. He’s winking one.', 'Εκατό μάτια! Θα τα μετρήσω. … Ενενήντα εννιά. Κλείνει το ένα.'));
  G.letterbox = 0; m.stay = ARG_X - 300; G.bounds = [ARG_X - 270, ARG_X + 270]; G.camLock = ARG_X - LW / 2; G.check = { x: ARG_X - 160 }; A.C = argConf(); A.hp = A.maxHp = A.C.need; G.boss = { a: A, name: T('Le paon d’Argos', 'Argus’s peacock', 'Το παγώνι του Άργου'), t: 0 }; Audio.playMusic('lion'); }
