    if (m.st === 'volleyTell') { if (m.t > C.volleyTell) { m.st = 'idle'; m.t = 0; setAnim(a, 'give'); for (const dx of [-40, 0, 40]) { const tx = clamp(m.tx + dx, OLY_L, OLY_R), sx = a.x, sy = a.y - 40, T2 = 0.9; G.objs.push({ kind: 'peye', x: sx, y: sy, vx: (tx - sx) / T2, vy: -140, g: (2 * ((a.y - 4) - sy - (-140) * T2)) / (T2 * T2), t: 0 }); } } return; }
