    if (m.st === 'charge') { a.x += m.dir * 300 * dt; a.face = m.dir; if (!m.hit && Math.abs(h.x - a.x) < 16 && h.ground && h.state !== 'dead') { m.hit = true; hurtHero(1, a.x - m.dir * 10); } if (!m.past && (a.x - h.x) * m.dir > 0) m.past = a.x; if (a.x < OLY_L + 10 || a.x > OLY_R - 10 || (m.past != null && Math.abs(a.x - m.past) > 56)) { a.x = clamp(a.x, OLY_L + 10, OLY_R - 10); m.past = null; m.st = 'rest'; m.t = 0; m.hits = Save.d.heroic ? 0 : (m.hits || 0); setAnim(a, 'idle'); Audio.sfx('smash'); G.shake = 0.3; if (!a.toldRest) { a.toldRest = true; G.toast = { plain: true, text: T('Son sceptre s’est planté dans le marbre ! Frappe !', 'Her sceptre is stuck in the marble! Strike!', 'Το σκήπτρο της καρφώθηκε στο μάρμαρο! Χτύπα!'), t: 0 }; } } return; }
